import {motionPreference} from './preferences.js';
const EASE='cubic-bezier(.16,1,.3,1)';
// Shared by touch, keyboard and pointer interactions. Never hides content at rest.
export function setupChoreography(){
 const running=new Set(),observed=new WeakSet(),visibleArt=new Set();
 const canAnimate=()=>!motionPreference.matches&&!document.hidden&&!document.body.classList.contains('is-watching');
 function play(el,frames,options={}){if(!canAnimate()||!el?.animate)return;const animation=el.animate(frames,{duration:680,easing:EASE,...options});running.add(animation);const clean=()=>running.delete(animation);animation.addEventListener('finish',clean,{once:true});animation.addEventListener('cancel',clean,{once:true});return animation;}
 // Wrap actual lines, preserving text nodes, emphasis and selectable accessible text.
 for(const heading of document.querySelectorAll('main h2')){const lines=[];let group=[];for(const node of [...heading.childNodes]){if(node.nodeName==='BR'){lines.push(group);group=[];}else group.push(node);}lines.push(group);heading.replaceChildren();for(const nodes of lines){const line=document.createElement('span'),inner=document.createElement('span');line.className='motion-line';inner.className='motion-line-content';inner.append(...nodes);line.append(inner);heading.append(line,document.createTextNode("\n"));}}
 const enter=new IntersectionObserver(entries=>{let batch=0;for(const entry of entries){if(!entry.isIntersecting)continue;const el=entry.target;enter.unobserve(el);if(el.matches('h2')){el.querySelectorAll('.motion-line-content').forEach((line,i)=>play(line,[{transform:'translateY(105%)',opacity:.2},{transform:'translateY(0)',opacity:1}],{duration:850,delay:i*85}));}else{play(el,[{opacity:0,transform:'translateY(22px)'},{opacity:1,transform:'translateY(0)'}],{duration:640,delay:Math.min(batch++*55,220)});}el.classList.add('motion-entered');}},{threshold:.12});
 function watch(el){if(observed.has(el))return;observed.add(el);enter.observe(el);}
 document.querySelectorAll('main h2,.timeline article,.skill-groups>div,.chapter-index a,.certificate-card,.cinema,.interest-tags span').forEach(watch);
 const gallery=document.querySelector('#certificate-grid'),galleryChanges=new MutationObserver(records=>{for(const record of records)for(const node of record.removedNodes)if(node.nodeType===1)enter.unobserve(node);gallery.querySelectorAll('.certificate-card').forEach(watch);});galleryChanges.observe(gallery,{childList:true});
 const artObserver=new IntersectionObserver(entries=>{for(const e of entries){e.target.classList.toggle('motion-inview',e.isIntersecting);if(e.isIntersecting)visibleArt.add(e.target);else visibleArt.delete(e.target);}updateScroll();},{threshold:.05});
 document.querySelectorAll('.project-visual,.article-art,.section-top').forEach(el=>artObserver.observe(el));
 function updateScroll(){if(!canAnimate())return;const amount=innerWidth<700?5:12;for(const el of visibleArt){if(el.matches('.section-top'))continue;const r=el.getBoundingClientRect(),offset=Math.max(-1,Math.min(1,(r.top+r.height/2-innerHeight/2)/innerHeight));el.style.setProperty('--scroll-drift',`${(offset*amount).toFixed(2)}px`);}}
 const nav=document.querySelector('header nav');const menuChanges=new MutationObserver(()=>{if(nav.classList.contains('open'))nav.querySelectorAll('a').forEach((a,i)=>play(a,[{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:480,delay:i*45}));});menuChanges.observe(nav,{attributes:true,attributeFilter:['class']});
 function feedback(e){const el=e.target.closest('.primary,.contact-button,.project-button,.certificate-card,.filters button,.gallery-view button,.chapter-index a');if(!el||el.disabled||!canAnimate())return;play(el,[{scale:'1'},{scale:'.975',offset:.38},{scale:'1'}],{duration:300,easing:'cubic-bezier(.2,.7,.3,1)'});if(!el.matches('.primary,.project-button,.filters button,.gallery-view button'))return;const r=el.getBoundingClientRect(),ring=document.createElement('span');ring.className='interaction-ring';ring.setAttribute('aria-hidden','true');ring.style.left=`${e.clientX-r.left}px`;ring.style.top=`${e.clientY-r.top}px`;el.append(ring);const a=play(ring,[{transform:'translate(-50%,-50%) scale(0)',opacity:.35},{transform:'translate(-50%,-50%) scale(1)',opacity:0}],{duration:550,easing:'ease-out'});if(a){a.addEventListener('finish',()=>ring.remove(),{once:true});a.addEventListener('cancel',()=>ring.remove(),{once:true});}else ring.remove();}
 function keyboard(e){if(!['Enter',' '].includes(e.key)||e.repeat)return;const el=e.target.closest('a,button');if(el&&canAnimate())play(el,[{scale:'1'},{scale:'.98'},{scale:'1'}],{duration:260});}
 document.addEventListener('pointerdown',feedback,{passive:true});document.addEventListener('keydown',keyboard);
 function refresh(){document.documentElement.dataset.pagePaused=String(document.hidden||document.body.classList.contains('is-watching'));if(motionPreference.matches){for(const a of running)a.cancel();for(const el of document.querySelectorAll('[style*="--scroll-drift"]'))el.style.removeProperty('--scroll-drift');}else for(const a of running){if(canAnimate())a.play();else a.pause();}}
 motionPreference.addEventListener('change',refresh);document.addEventListener('visibilitychange',refresh);document.addEventListener('portfolio:playback',refresh);refresh();
 return {updateScroll,destroy(){enter.disconnect();artObserver.disconnect();galleryChanges.disconnect();menuChanges.disconnect();for(const a of running)a.cancel();document.removeEventListener('pointerdown',feedback);document.removeEventListener('keydown',keyboard);document.removeEventListener('visibilitychange',refresh);document.removeEventListener('portfolio:playback',refresh);motionPreference.removeEventListener('change',refresh);}};
}
